# Вариант А: библиотека и банк. Формат задачи см. build.py
V = 'A'
TASKS = [
dict(n=1, pts=0.5, title='Выдача книги', topics='if / elif / else, not in',
 text='В окне уже заданы список `readers` и три фразы: `ok_msg`, `late_msg`, `other_msg`. Вводятся имя читателя и число дней просрочки прошлой книги.\n\nЕсли имени нет в списке читателей, напечатайте `other_msg`. Если читатель есть и просрочки нет (0 дней), напечатайте `ok_msg`. Если читатель есть и просрочка есть, напечатайте `late_msg`.',
 fin='Первая строка — имя, вторая — число дней (целое).', fout='Одна из трёх фраз.',
 pre="readers = ['Ольга', 'Павел', 'Иван']\nok_msg = 'Книга выдана'\nlate_msg = 'Сначала верните прошлую книгу'\nother_msg = 'Сначала запишитесь в библиотеку'",
 inputs=[['Ольга','0'],['Павел','5'],['Анна','0'],['Иван','1'],['Ольга','30'],['ольга','0']],
 sol="name = input()\ndays = int(input())\n\nif name not in readers:\n    print(other_msg)\nelif days == 0:\n    print(ok_msg)\nelse:\n    print(late_msg)\n",
 hint='Сначала отсеките тех, кого нет в списке (`not in`), потом разберите просрочку через `elif` и `else`. Не забудьте `int` для дней.',
 idea='Три исхода — цепочка `if / elif / else`: нет в списке; в списке без просрочки; в списке с просрочкой.',
 steps=['`name = input()` читает имя, `days = int(input())` читает дни и сразу делает их числом.','`name not in readers` — первая проверка: если читателя нет, остальное не важно.','`elif days == 0` выполняется только когда читатель есть; сравнение на равенство — два знака `==`.','`else` — читатель есть и просрочка больше нуля.'],
 mist=['Забыли `int(...)`: сравнение `"0" == 0` даёт `False`, и все получат `late_msg`.','Поставили `=` вместо `==` в условии: будет `SyntaxError`.','Регистр важен: `ольга` не равно `Ольга`, такого читателя в списке нет.']),
dict(n=2, pts=1, title='Новые книги', topics='while True, break, split, список',
 text='Вводятся строки вида `название:год` (год — целое число), пока не будет введено слово `END`.\n\nНапечатайте список названий книг, изданных **после 2000 года** (строго), в порядке ввода. Если таких нет, напечатайте пустой список.',
 fin='Строки `название:год`, последняя строка — `END`.', fout='Список названий в квадратных скобках, как печатает `print(список)`.',
 pre='',
 inputs=[['Мастер и Маргарита:1967','Дюна:1965','Гарри Поттер:2001','END'],['END'],['Книга:2000','Другая:2024','Третья:1999','Четвёртая:2010','END'],['Война и мир:1869','END'],['А:2001','END']],
 sol="new = []\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    title, year = line.split(':')\n    if int(year) > 2000:\n        new.append(title)\n\nprint(new)\n",
 hint='Список создайте до цикла. Строку режьте по двоеточию: `title, year = line.split(":")`. Год — строка, нужен `int`.',
 idea='Читаем строки в бесконечном цикле, на слове `END` выходим через `break`, остальное разбираем и фильтруем.',
 steps=['`new = []` создаём **до** цикла, иначе список обнулялся бы на каждой строке.','`while True:` — читаем, пока сами не прервём цикл.','`line == "END"` → `break`: выходим, не обрабатывая слово `END`.','`title, year = line.split(":")` — две части строки в две переменные.','`int(year) > 2000` — строго «после 2000», значит 2000 не подходит.'],
 mist=['Список создан внутри цикла — в конце останется только последняя книга.','Не сделали `int(year)`: сравнение строки `"2001"` с числом 2000 — ошибка `TypeError`.','Поставили `>=`: книга 2000 года попадёт в список зря.'],
 trace='Ввод `Мастер и Маргарита:1967`: 1967 не больше 2000, пропускаем. `Дюна:1965` — пропускаем. `Гарри Поттер:2001` — 2001 больше 2000, добавляем. `END` — выходим. Печатаем `[\'Гарри Поттер\']`.'),
dict(n=3, pts=0.5, title='Новая книга в каталоге', topics='split(", "), not in, append',
 text='В первой строке названия книг каталога через «запятая + пробел». Во второй — название новой книги.\n\nЕсли такой книги в каталоге ещё нет, добавьте её в конец списка. Напечатайте список.',
 fin='Первая строка — названия через `, `. Вторая — одно название.', fout='Список названий в квадратных скобках.',
 pre='',
 inputs=[['Дюна, Эмма, Идиот','Белая гвардия'],['Дюна, Эмма','Эмма'],['Ревизор','Ревизор'],['Мцыри, Дубровский','Анна Каренина'],['Дюна','дюна']],
 sol="books = input().split(', ')\nnew_book = input()\n\nif new_book not in books:\n    books.append(new_book)\n\nprint(books)\n",
 hint='Строку с названиями разбейте `split(", ")` (запятая и пробел). Проверка — `not in`, добавление — `append`.',
 idea='Превращаем строку в список, проверяем, нет ли там новой книги, и добавляем при необходимости.',
 steps=['`input().split(", ")` — строка превращается в список названий; названия с пробелом внутри остаются целыми.','`new_book not in books` — истина, если такой книги в списке нет.','`books.append(new_book)` добавляет в конец и меняет сам список.','Печатаем в конце, чтобы вывод был и когда книга уже была.'],
 mist=['`split()` без аргумента режет и по пробелам внутри названий, и запятые остаются в кусках.','`print` внутри `if`: если книга уже есть, ничего не напечатается.','Результат `append` присвоили переменной: `books = books.append(...)` даёт `None`.']),
dict(n=4, pts=1, title='Выгодные вклады', topics='два списка, range(len())',
 text='В первой строке названия вкладов через пробел, во второй — их годовые ставки (целые числа процентов) в том же порядке. В третьей — минимальная ставка, которая вас устраивает.\n\nНапечатайте названия вкладов, у которых ставка **не меньше** минимальной, каждое с новой строки.',
 fin='Три строки: названия, ставки, минимальная ставка.', fout='Названия по одному на строке или пустой вывод.',
 pre='',
 inputs=[['Старт Лето Мир Плюс','8 12 10 15','10'],['А Б','5 6','7'],['Один','9','9'],['Весна Осень Зима','11 7 11','11'],['Х У','20 1','1']],
 sol="deposits = input().split()\nrates = input().split()\nneed = int(input())\n\nfor i in range(len(deposits)):\n    if int(rates[i]) >= need:\n        print(deposits[i])\n",
 hint='Названия и ставки лежат в двух списках, связь между ними — одинаковый номер. Переберите номера через `range(len(...))`. Ставки — строки, нужен `int`.',
 idea='Идём по номерам: по номеру берём и название, и ставку, сравниваем ставку с минимальной.',
 steps=['`deposits` и `rates` — списки **строк**; число из `rates` нужно через `int(rates[i])`.','`range(len(deposits))` — номера 0, 1, 2, …','`int(rates[i]) >= need` — «не меньше», то есть `>=`.','Печатаем `deposits[i]` — название с тем же номером.'],
 mist=['`>` вместо `>=`: вклад со ставкой ровно как минимальная пропадёт.','Сравнили `rates[i] >= need` без `int`: строка с числом — ошибка `TypeError`.','Напечатали `rates[i]` вместо `deposits[i]`.']),
dict(n=5, pts=0.75, title='Общие читатели', topics='множества, пересечение',
 text='Две строки: имена читателей первого филиала и второго (через пробел).\n\nНапечатайте через пробел имена, которые есть **в обоих** филиалах, в алфавитном порядке. Если общих нет, напечатайте пустую строку.',
 fin='Две строки, имена через пробел.', fout='Имена через пробел в алфавитном порядке или пустая строка.',
 pre='',
 inputs=[['Аня Борис Вера','Вера Глеб Аня'],['Аня','Борис'],['Дима Егор Жанна','Жанна Дима Егор'],['Зоя','Зоя Ира'],['Паша Рита','Сергей Тоня']],
 sol="first = set(input().split())\nsecond = set(input().split())\n\nprint(*sorted(first & second))\n",
 hint='Превратите обе строки во множества, найдите пересечение `&`, отсортируйте `sorted` и распечатайте через `print(*...)`.',
 idea='Общие элементы двух множеств — их пересечение. Порядок во множестве не определён, поэтому сортируем.',
 steps=['`set(input().split())` — строка → список → множество.','`first & second` — имена, которые есть в обоих множествах.','`sorted(...)` даёт список по алфавиту.','`print(*список)` печатает элементы через пробел; для пустого списка получится пустая строка.'],
 mist=['`print(first & second)` печатает фигурные скобки и порядок случайный.','`|` вместо `&`: получатся все читатели, а не общие.','Забыли `sorted`: порядок имён может отличаться от ожидаемого.']),
dict(n=6, pts=1.25, title='Невостребованные жанры', topics='множества, объединение и разность',
 text='Три строки с названиями жанров через запятую **без пробела** (в названиях пробелы бывают): жанры, которые читает Аня; жанры, которые читает Борис; все жанры библиотеки.\n\nНапечатайте, сколько жанров библиотеки **не читает ни Аня, ни Борис**.',
 fin='Три строки, жанры через запятую.', fout='Одно число.',
 pre='',
 inputs=[['Детектив,Фэнтези','Фэнтези,Поэзия','Детектив,Фэнтези,Поэзия,Научная фантастика,Драма'],['А б,В г','Д е','Ж з'],['Х','Х','Х'],['Роман','Роман,Эссе','Роман,Эссе,Комикс'],['Драма,Поэзия','Поэзия','Драма,Поэзия,Сказки']],
 sol="anna = set(input().split(','))\nboris = set(input().split(','))\nlibrary = set(input().split(','))\n\nchosen = anna | boris\nprint(len(library - chosen))\n",
 hint='«Ни Аня, ни Борис» — это жанры, которых нет в объединении их множеств. Сначала объедините `|`, потом вычтите `-` из множества библиотеки.',
 idea='Собираем всё, что читает хотя бы один (объединение), и вычитаем это из жанров библиотеки.',
 steps=['Разделитель — запятая без пробела: `.split(",")`. Без аргумента названия с пробелами разорвутся.','`anna | boris` — жанры, которые читает хотя бы один из двоих.','`library - chosen` — жанры библиотеки, которых нет среди читаемых.','`len(...)` — сколько их.'],
 mist=['`split()` вместо `split(",")`: «Научная фантастика» разорвётся на два жанра.','Вычли в другую сторону `chosen - library`: получится совсем другое множество.','`&` вместо `|` в первом шаге: получатся жанры «читают оба».']),
dict(n=7, pts=0.75, title='Клиенты банка', topics='словарь, перебор ключей',
 text='В окне задан словарь `accounts`: клиент → банк, в котором у него счёт. Вводится название банка.\n\nНапечатайте клиентов этого банка, каждого с новой строки, в порядке словаря. Если таких нет, ничего не печатайте.',
 fin='Одна строка — название банка.', fout='Имена по одному на строке или пустой вывод.',
 pre="accounts = {'Анна': 'Север', 'Борис': 'Юг', 'Вера': 'Север', 'Глеб': 'Запад', 'Дарья': 'Юг', 'Егор': 'Север'}",
 inputs=[['Север'],['Юг'],['Запад'],['Восток'],['север']],
 sol="bank = input()\n\nfor name in accounts:\n    if accounts[name] == bank:\n        print(name)\n",
 hint='Цикл `for name in accounts` перебирает **ключи** (клиентов). Значение (банк) берётся как `accounts[name]`.',
 idea='Идём по клиентам и печатаем тех, у кого банк совпадает с введённым.',
 steps=['`for name in accounts:` — переменная `name` по очереди получает каждого клиента.','`accounts[name]` — банк этого клиента.','`== bank` — совпадение с введённым названием.','Печатаем `name`, а не банк.'],
 mist=['Напечатали `accounts[name]`: получится название банка вместо клиента.','Ждали, что цикл даст значения: он перебирает ключи.','Сравнили без учёта регистра: `север` не равно `Север`.']),
dict(n=8, pts=1.25, title='Филиалы без перегрузки', topics='словарь списков, max',
 text='В окне задан словарь `branches`: филиал → список числа посетителей за четыре дня. Вводится лимит.\n\nНапечатайте филиалы, у которых **в каждый из дней** посетителей **строго меньше** лимита, каждый с новой строки, в порядке словаря.',
 fin='Одна строка — лимит (целое число).', fout='Названия филиалов по одному на строке или пустой вывод.',
 pre="branches = {'Центральный': [120, 95, 140, 110], 'Северный': [60, 75, 80, 70], 'Южный': [200, 180, 150, 170], 'Речной': [90, 85, 95, 100]}",
 inputs=[['150'],['100'],['50'],['201'],['141']],
 sol="limit = int(input())\n\nfor branch in branches:\n    if max(branches[branch]) < limit:\n        print(branch)\n",
 hint='«В каждый день меньше лимита» — это то же, что «самый загруженный день меньше лимита». Используйте `max`.',
 idea='Вместо проверки каждого дня сравниваем с лимитом максимум в списке.',
 steps=['`branches[branch]` — список посетителей филиала.','`max(...)` — самый большой день.','Если самый большой день меньше лимита, то и все остальные меньше. Строго «меньше» — это `<`.','Печатаем **ключ** `branch`, а не список.'],
 mist=['`min` вместо `max`: условие станет «хотя бы в один день меньше лимита».','`<=` вместо `<`: филиал с пиком ровно в лимит попадёт зря.','Напечатали `branches[branch]` — список посетителей вместо названия.']),
dict(n=9, pts=1.5, title='Книги в коробках', topics='цикл, // и %',
 text='Первая строка — количество книг в каждом заказе, через пробел. Вторая — вместимость одной коробки (целое число). Каждую коробку заполняют только полностью, остаток книг каждого заказа остаётся на полке.\n\nНапечатайте через пробел два числа: сколько **всего полных коробок** получится и сколько **всего книг останется** на полке.',
 fin='Две строки: заказы, вместимость коробки.', fout='Два числа через пробел.',
 pre='',
 inputs=[['25 40 10','10'],['7','10'],['100 100','25'],['1 2 3','2'],['50','7']],
 sol="orders = input().split()\nbox = int(input())\n\nfull = 0\nrest = 0\nfor order in orders:\n    full += int(order) // box\n    rest += int(order) % box\n\nprint(full, rest)\n",
 hint='Для одного заказа число полных коробок — `//` (целочисленное деление), остаток — `%`. Заведите два счётчика до цикла.',
 idea='Для каждого заказа делим нацело на вместимость и берём остаток, итоги копим в двух счётчиках.',
 steps=['`orders` — список **строк**, каждую берём как `int(order)`.','`int(order) // box` — сколько полных коробок в заказе.','`int(order) % box` — сколько книг осталось.','`full` и `rest` создаём **до** цикла, печатаем после.'],
 mist=['Обнулили счётчики внутри цикла: останутся данные последнего заказа.','Забыли `int(order)`: деление `//` со строкой — ошибка.','Посчитали по общей сумме книг: остаток на заказ даёт другое число.'],
 trace='Заказы `25 40 10`, коробка 10: 25 → 2 коробки, остаток 5; 40 → 4, остаток 0; 10 → 1, остаток 0. Итого 7 полных коробок и 5 книг. Печатаем `7 5`.'),
dict(n=10, pts=1.5, title='Самый популярный жанр', topics='while True, словарь-накопитель, максимум',
 text='Вводятся строки вида `жанр,выдач` (число выдач — целое **положительное**), пока не будет введено слово `END`. Один жанр может встретиться несколько раз.\n\nНайдите жанр с **наибольшим суммарным** числом выдач. Напечатайте его название и число через пробел. Гарантируется, что есть хотя бы одна строка. Если у нескольких жанров одинаковый максимум — выведите того, кто встретился раньше.',
 fin='Строки `жанр,выдач`, последняя строка — `END`.', fout='Название и число через пробел.',
 pre='',
 inputs=[['Детектив,10','Поэзия,4','Детектив,15','Поэзия,6','Роман,25','END'],['Роман,5','END'],['А,10','Б,10','END'],['Х,100','У,50','У,60','END'],['Драма,3','Сказки,2','Драма,1','Сказки,7','END']],
 sol="totals = {}\n\nwhile True:\n    line = input()\n    if line == 'END':\n        break\n    genre, count = line.split(',')\n    if genre in totals:\n        totals[genre] += int(count)\n    else:\n        totals[genre] = int(count)\n\nbest = ''\nbest_sum = 0\nfor genre in totals:\n    if totals[genre] > best_sum:\n        best_sum = totals[genre]\n        best = genre\n\nprint(best, best_sum)\n",
 hint='Два шага: (1) в цикле копите суммы в словаре; (2) после цикла найдите максимум. Для строгого сравнения при равных суммах берите `>`, а не `>=`.',
 idea='Сначала собираем словарь «жанр → выдач», потом ищем ключ с наибольшим значением.',
 steps=['`totals = {}` — до цикла.','Если жанр уже есть в словаре, прибавляем: `totals[genre] += int(count)`, иначе создаём запись.','Выдач всегда больше нуля, поэтому стартовый максимум `0` подходит: любое значение его заменит.','`>` (строго) оставляет первого из равных, как требует условие.','`print(best, best_sum)` с запятой печатает через пробел.'],
 mist=['`max(totals)` без `key` берёт максимум **по алфавиту жанров**, а не по числу выдач.','`>=` вместо `>`: при равных суммах выберется последний, а не первый.','Забыли `int(count)`: строки склеиваются (`"10" + "15"`).'],
 trace='Детектив: 10, затем 15 → 25. Поэзия: 4, затем 6 → 10. Роман: 25. Максимум 25: Детектив встретился раньше Романа, поэтому ответ `Детектив 25`.'),
]
